import AWS from "aws-sdk";
export default {
  props: {
    createFolderDialog: Boolean,
    orgResponse: Object,
    primaryKey: String
  },
  watch: {
    createFolderDialog: {
      async handler() {
        if (this.createFolderDialog == true) {
          //   this.$refs.form.reset();
        }
      },
      immediate: true
    }
  },
  data() {
    return {
      folderName: "",
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.folderName = "";
      this.$emit("clicked", 0);
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.create_folder();
      }
    },
    create_folder() {
      var self = this;
      const s3 = new AWS.S3({
        region: this.orgResponse.s3_details.region,
        accessKeyId: this.orgResponse.s3_details.access_key,
        secretAccessKey: this.orgResponse.s3_details.secret_key
      }); // Replace with your S3 region
      const params = {
        Bucket: this.orgResponse.s3_details.bucket_name,
        Key: this.primaryKey != "" ? this.primaryKey + this.folderName + "/" : "Cabinet" + "/" + this.orgResponse.organization.organization_id + "/",
        Body: ""
      };
      s3.upload(params, (err, data) => {
        if (err) {
          self.loading = false;
        } else {
          self.$emit("folderSuccess", "Created Successfully");
          self.folderName = "";
          self.loading = false;
        }
      });
    }
  }
};
